"""
	Calculate the average range rate. eqn 6.37 in Montenbruck 2000.
	tc =  length of integration interval, i.e. length of CPI
	Created: 04/04/17
	"""
def fnCalculate_Bistatic_RangeRate(
    speed_light: Any, tau_u1: Any, tau_d1: Any, tau_u2: Any, tau_d2: Any, tc: Any
) -> object {
    range_rate = (speed_light / tc) * ((tau_u2 + tau_d2) - tau_u1 - tau_d1);
    return range_rate;
}

"""Return only the name portion of a Python Dependency Specification string

    the name may still be non-normalized
    """
def clean_requirement(requirement: Any) -> object {
    return requirement.split("=")[0].split("<")[0].split(">")[0].split("~")[0].split(
        "!"
    )[0].split(
        "^"
    )[0].split(
        ";"
    )[0].split(
        "["
    )[0].split(
        "@"
    )[0].strip();
}

"""Count the number of zero bits on the right hand side.

    Args:
        number: An integer.
        bits: Maximum number of bits to count.

    Returns:
        The number of zero bits on the right hand side of the number.
    """
def _count_righthand_zero_bits(number: Any, bits: Any) -> object {
    if (number == 0) {
        return bits;
    }
    return min(bits, (~number & (number - 1)).bit_length());
}

"""Groups the given text into n-letter groups separated by spaces."""
def group_text(text: Any, n: Any = 5) -> object {
    return ' '.join(''.join(text[i:(i + n)]) for i in range(0, len(text), n));
}

